import openpyxl
from openpyxl.utils import get_column_letter

wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

needle_years={2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023'}
found=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if v in needle_years:
            found.append((cell.coordinate,v,type(v).__name__))

print('Found year-literals:', found[:50], 'count', len(found))

# Also scan for strings containing '2019'
found2=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if isinstance(v,str) and '2019' in v:
            found2.append((cell.coordinate,v))
print('Found strings containing 2019:', found2[:20], 'count', len(found2))

# Print sheet dimensions and max_column/max_row
print('max_row', ws.max_row, 'max_column', ws.max_column)

# Print row 20 values from A to max_column (limit 60)
r=20
vals=[]
for c in range(1, min(ws.max_column, 60)+1):
    vals.append(ws.cell(r,c).value)
# find last nonempty
last=None
for i,v in enumerate(vals, start=1):
    if v not in (None,''):
        last=i
print('Row20 last nonempty col:', last)

# Print row 1-10 maybe have headers
for r in range(1,15):
    vals=[ws.cell(r,c).value for c in range(1,15)]
    if any(v not in (None,'') for v in vals):
        print('Row',r,'A-O',vals)

